<script lang="ts">
  import { onMount } from 'svelte';
  import InvoiceTable from '../components/InvoiceTable.svelte';
  import { api, date, environment, message, rupiah } from '../lib/api';
  import type { Dashboard, ApiKey, Invoice, User } from '../lib/api';
  let { user, oncreate }: { user: User; oncreate: () => void } = $props();
  let data = $state<Dashboard | null>(null); let keys = $state<ApiKey[]>([]); let loading = $state(true); let error = $state('');
  async function load() {
    loading = true; error = '';
    try { const [dashboard, apiKeys] = await Promise.all([api<Dashboard>('/api/dashboard'), api<ApiKey[]>('/api/keys')]); data = dashboard; keys = apiKeys; }
    catch (e) { error = message(e); } finally { loading = false; }
  }
  function changed(_invoice: Invoice) { void load(); }
  onMount(load);
</script>
<div class="page-heading"><div><span class="eyebrow">{$environment === 'sandbox' ? 'Ringkasan sandbox' : 'Ruang pembayaran produksi'}</span><h1>Pembayaran, dalam kendali.</h1><p class="muted">Halo, {user.name}. Pantau invoice yang perlu Anda tindak lanjuti.</p></div><button class="primary" onclick={oncreate}>+ Buat invoice</button></div>
{#if loading}<p class="loading" role="status">Memuat ringkasan {$environment}…</p>{:else if error}<div class="notice error" role="alert"><p>{error}</p><button class="secondary" onclick={load}>Muat ulang ringkasan</button></div>{:else if data}
<section class="balance-panel" aria-labelledby="balance-title"><div><span class="eyebrow" id="balance-title">{$environment === 'sandbox' ? 'Total invoice ditandai lunas oleh simulator' : 'Total pembayaran terverifikasi'}</span><p class="balance">{rupiah(data.paid_total)}</p><p>{data.paid_count} invoice lunas · Seluruh riwayat {$environment}</p></div><div class="balance-footnote"><strong>{$environment === 'sandbox' ? 'Tidak ada uang diterima.' : 'Dana langsung ke merchant.'}</strong><p>{$environment === 'sandbox' ? 'Angka ini hasil simulasi, bukan pendapatan atau saldo merchant.' : 'Ini total invoice terverifikasi, bukan saldo yang disimpan di QRIS Gateway.'}</p></div></section>
<div class="dashboard-summary"><p><strong>{data.pending_count} invoice menunggu</strong><span class="muted">Senilai {rupiah(data.pending_total)}</span></p><p><strong>{$environment === 'sandbox' ? 'Sandbox tanpa dompet nyata' : data.daily_limit != null ? 'Gratis selamanya' : 'Tanpa batas kuota harian gratis'}</strong><span class="muted">{$environment === 'sandbox' ? 'Uji alur pembayaran dan webhook tanpa transfer' : data.subscription_active ? `Sewa sampai ${date(data.subscription_expires_at)}` : '5 invoice produksi per hari WIB, sewa bersifat opsional'}</span></p></div>
{#if $environment === 'production' && data.daily_limit != null}<section class="quota-panel" aria-labelledby="quota-title"><div class="section-heading"><h2 id="quota-title">Kuota produksi hari ini</h2><a href="/subscription" class="text-link">Sewa 7/30 hari</a></div><p><strong>{data.daily_used ?? 0} dari {data.daily_limit} invoice dibuat</strong> · Sisa {data.daily_remaining ?? 0}</p><meter min="0" max={data.daily_limit} value={data.daily_used ?? 0} aria-label="Kuota invoice produksi terpakai"></meter><p class="small muted">Reset pukul 00.00 WIB{data.resets_at ? ` (berikutnya ${new Intl.DateTimeFormat('id-ID', { timeZone: 'Asia/Jakarta', dateStyle: 'medium', timeStyle: 'short' }).format(new Date(data.resets_at))} WIB)` : ''}. Hanya invoice produksi berhasil dibuat memakai kuota. Pemeriksaan invoice dan rekonsiliasi tetap berjalan saat kuota habis.</p></section>{/if}
<section class="section"><div class="section-heading"><div><h2>Menunggu pembayaran</h2><p class="muted">{$environment === 'sandbox' ? 'Buka checkout untuk mencoba status lunas, gagal, atau kedaluwarsa.' : 'Periksa status setelah pelanggan membayar nominal yang sesuai.'}</p></div><a class="text-link" href="/transactions">Semua transaksi</a></div><InvoiceTable invoices={data.invoices.filter(i => i.status === 'pending')} onchanged={changed} compact /></section>
<section class="onboarding section" aria-labelledby="ready-title"><div><span class="eyebrow">Pengaturan merchant</span><h2 id="ready-title">Siap menerima QRIS?</h2><p class="muted">Akun gratis bisa langsung membuat invoice setelah dompet siap.</p></div><ol class="checklist"><li><span class="step">01</span><div><strong>Hubungkan dompet produksi</strong><p>{data.connections.some(c => c.managed && c.active && c.configured) ? 'Dompet terkonfigurasi tersedia. Uji token/sesi sebelum digunakan.' : 'Tambahkan QRIS, lalu login/import GoPay atau token ShopeePay. Sandbox tidak memerlukannya.'}</p></div><a href="/connections" class="button quiet">Kelola dompet</a></li><li><span class="step">02</span><div><strong>Integrasikan aplikasi jika diperlukan</strong><p>{keys.length ? `${keys.length} kunci API ${$environment} tersimpan.` : 'Buat kunci terpisah untuk produksi dan sandbox. Dashboard tidak memerlukan kunci.'}</p></div><a href="/integrations" class="button quiet">API &amp; webhook</a></li><li><span class="step">03</span><div><strong>Pelajari alur dan batasnya</strong><p>Onboarding, scanner, simulasi, HMAC, dan rekonsiliasi dijelaskan dalam panduan.</p></div><a href="/guide" class="button quiet">Baca panduan</a></li></ol></section>{/if}
